/// <summary>
/// PricingAttribute of table <c>InventTable</c> field PdsCWWMSStandardPalletQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTablePdsCWWMSStandardPalletQty extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, PdsCWWMSStandardPalletQty);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by PdsCWWMSStandardPalletQty
    {
        if (! ret.in(inventTable.PdsCWWMSStandardPalletQty))
        {
            ret.add(inventTable.PdsCWWMSStandardPalletQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, PdsCWWMSStandardPalletQty));
    qbr.value(queryValue(_value));
}
